// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    // fuzzed params: depositor (actor) and amount to deposit; the fuzzer will search for an amount and actor
    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep depositor non-zero and amount within a reasonable range (but wide)
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // deploy an adversarial reentrant recipient that will re-enter c.withdrawBalance exactly once
        Attacker attacker = new Attacker(c);

        // fund depositor so they can deposit
        vm.deal(depositor, amount);
        vm.startPrank(depositor);
        // depositor calls addToBalance paying 'amount'
        c.addToBalance{value: amount}();
        vm.stopPrank();

        // now transfer the balance from depositor to the attacker by setting up attacker as the caller
        // we simulate the depositor being the attacker by giving attacker the same balance in c via a deposit
        // (the key point is attacker will call withdrawBalance and re-enter)
        // fund attacker externally so it can call withdrawBalance (its internal receive will re-enter once)
        vm.deal(address(attacker), 0);

        // To make attacker be the withdraw caller, first deposit into c under attacker address
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.addToBalance{value: amount}();

        // Record attacker's balance before withdraw: how much ETH the attacker contract holds externally
        uint256 beforeExternal = address(attacker).balance;

        // Now have attacker call withdrawBalance; the Attacker.receive will re-enter once into c.withdrawBalance
        // We wrap in try/catch to observe whether withdrawBalance reverts (should not in reference)
        bool ok;
        try attacker.goWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdraw completes, the reference implementation must have sent the full pre-withdraw
        // user balance to the caller (attacker). Thus attacker.external balance should have increased by exactly 'amount'.
        // We assert that ok is true (no revert) AND the attacker received exactly 'amount'.
        // This is a single invariant reading observable state (address(attacker).balance).
        uint256 afterExternal = address(attacker).balance;

        // The ONE assertion: reference C ensures the caller receives their full stored balance (amount)
        // For the correct contract this holds for all inputs; the mutant can violate this for some inputs
        assertTrue(ok && afterExternal == beforeExternal + amount);
    }
}

// Minimal re-entrant attacker: on receiving ETH, it will re-enter c.withdrawBalance exactly once.
contract Attacker {
    Reentrance immutable target;
    bool private entered;

    constructor(Reentrance _t) {
        target = _t;
        entered = false;
    }

    // trigger withdraw from this contract
    function goWithdraw() external {
        // call target.withdrawBalance as this contract
        target.withdrawBalance();
    }

    // receive will re-enter exactly once
    receive() external payable {
        if (!entered) {
            entered = true;
            // re-enter withdrawBalance exactly once
            // This single reentrant call is allowed by the problem statement
            target.withdrawBalance();
        }
    }
}
